{
  "name": "session-state",
  "version": "0.3.2",
  "description": "Keeps a ledger of a long chat (what you asked and decided, what was learned, the files that matter, one line per turn) that the agent can read, and hands it back after Claude Code compacts.",
  "author": {
    "name": "Isaac Kargar"
  },
  "types": "./types/index.d.ts",
  "userConfig": {
    "openrouterKey": {
      "type": "string",
      "title": "OpenRouter API key",
      "description": "Used for the Jev gate. Leave empty to use the OPENROUTER_API_KEY environment variable. Default: empty.",
      "sensitive": true,
      "required": false
    },
    "gate": {
      "type": "string",
      "title": "Gate",
      "description": "jev: ask Jev (OpenRouter) first; off: Haiku reads every turn and nothing leaves Claude Code. Default: jev.",
      "options": [
        "jev",
        "off"
      ],
      "default": "jev"
    },
    "threshold": {
      "type": "number",
      "title": "Gate threshold",
      "description": "A turn gets a full extraction when Jev's probability is at least this; other turns get a cheap summary only. 0.63 keeps about 92% of passed turns on target and passes about 62% of the important ones (jev-1.14, eval/REPORT.md). Lower is noisier, higher misses more. Default: 0.63.",
      "default": 0.63,
      "min": 0,
      "max": 1
    },
    "jevModel": {
      "type": "string",
      "title": "Jev model",
      "description": "OpenRouter decision model id, e.g. jev-1.13 or jev-1.14. Default: jev-1.14 (the one the threshold is calibrated on). Empty means the default.",
      "default": "jev-1.14"
    },
    "haikuModel": {
      "type": "string",
      "title": "Extractor model",
